import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import axios from 'axios';

// Async thunk to fetch events
export const fetchEvents = createAsyncThunk('eventOwner/fetchEvents', async (_, { rejectWithValue }) => {
  try {
    const response = await axios.get('http://localhost:5000/api/events', {
      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
    });
    return response.data;
  } catch (error) {
    return rejectWithValue(error.response?.data.message || error.message);
  }
});

// Async thunk to create a new event
export const createEvent = createAsyncThunk('eventOwner/createEvent', async (eventData, { rejectWithValue }) => {
  try {
    const response = await axios.post('http://localhost:5000/api/events', eventData, {
      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
    });
    return response.data;
  } catch (error) {
    return rejectWithValue(error.response?.data.message || error.message);
  }
});

// Async thunk to fetch bookings
export const fetchBookings = createAsyncThunk('eventOwner/fetchBookings', async (_, { rejectWithValue }) => {
  try {
    const response = await axios.get('http://localhost:5000/api/bookings', {
      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
    });
    return response.data;
  } catch (error) {
    return rejectWithValue(error.response?.data.message || error.message);
  }
});

// Async thunk to fetch feedbacks
export const fetchFeedbacks = createAsyncThunk('eventOwner/fetchFeedbacks', async (_, { rejectWithValue }) => {
  try {
    const response = await axios.get('http://localhost:5000/api/feedbacks', {
      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
    });
    return response.data;
  } catch (error) {
    return rejectWithValue(error.response?.data.message || error.message);
  }
});

// Initial state
const initialState = {
  events: [],
  bookings: [],
  feedbacks: [],
  loading: false,
  error: null,
};

// Event owner slice
const eventOwnerSlice = createSlice({
  name: 'eventOwner',
  initialState,
  reducers: {
    resetError: (state) => {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    builder
      // Handle fetch events
      .addCase(fetchEvents.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchEvents.fulfilled, (state, action) => {
        state.loading = false;
        state.events = action.payload;
      })
      .addCase(fetchEvents.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      })

      // Handle create event
      .addCase(createEvent.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(createEvent.fulfilled, (state, action) => {
        state.loading = false;
        state.events.push(action.payload);
      })
      .addCase(createEvent.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      })

      // Handle fetch bookings
      .addCase(fetchBookings.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchBookings.fulfilled, (state, action) => {
        state.loading = false;
        state.bookings = action.payload;
      })
      .addCase(fetchBookings.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      })

      // Handle fetch feedbacks
      .addCase(fetchFeedbacks.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchFeedbacks.fulfilled, (state, action) => {
        state.loading = false;
        state.feedbacks = action.payload;
      })
      .addCase(fetchFeedbacks.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      });
  },
});

// Export the reducer and actions
export const { resetError } = eventOwnerSlice.actions;
export default eventOwnerSlice.reducer;


